#!/usr/bin/env node
// Run after editing anything in app/public (the web client bundle, its CSS, index.html…):
//   node tools/rehash-web.js
// Renames main_<id>_<hash>.js / .css after their content hash, updates every reference
// (index.html, the bundle's license comment, the service worker) and gives the service
// worker a new VERSION, so browsers drop their cached copy instead of serving the old one.
// The .br/.gz copies are generated by the Dockerfile, not here. Idempotent.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const pub = path.join(__dirname, '..', 'app', 'public');
const ls = () => fs.readdirSync(pub);
const hash = (buf) => crypto.createHash('sha256').update(buf).digest('hex').slice(0, 12);
const read = (f) => fs.readFileSync(path.join(pub, f), 'utf8');
const write = (f, s) => fs.writeFileSync(path.join(pub, f), s);

const NAME = /^(main_[0-9a-f]+)_[0-9a-f]+\.(js|css)$/;
const renames = {};
for (const ext of ['css', 'js']) {           // CSS first: index.html is part of the JS hash input
  const files = ls().filter((f) => NAME.test(f) && f.endsWith('.' + ext));
  if (files.length !== 1) throw new Error(`expected one main_*.${ext} in app/public, found ${files.length}`);
  const old = files[0];
  const base = old.match(NAME)[1];
  let body = read(old);
  if (ext === 'js') {
    // Hash the bundle together with index.html so an index-only change also busts caches.
    body = body.replace(/main_[0-9a-f]+_[0-9a-f]+\.js\.LICENSE\.txt/g, 'LICENSE');
  }
  // index.html without the asset names themselves (they are the output of this hash).
  const indexBody = read('index.html').replace(/main_[0-9a-f]+_[0-9a-f]+\.(js|css)/g, 'ASSET');
  const h = hash(ext === 'js' ? body + indexBody : body);
  const neu = `${base}_${h}.${ext}`;
  if (neu === old) { console.log(`${old}: unchanged`); continue; }
  renames[old] = neu;
  fs.renameSync(path.join(pub, old), path.join(pub, neu));
  if (ext === 'js' && fs.existsSync(path.join(pub, old + '.LICENSE.txt'))) {
    fs.renameSync(path.join(pub, old + '.LICENSE.txt'), path.join(pub, neu + '.LICENSE.txt'));
    write(neu, read(neu).split(old + '.LICENSE.txt').join(neu + '.LICENSE.txt'));
  }
  for (const stale of [old + '.br', old + '.gz']) {
    if (fs.existsSync(path.join(pub, stale))) fs.unlinkSync(path.join(pub, stale));
  }
  console.log(`${old} -> ${neu}`);
}

let index = read('index.html');
for (const [o, n] of Object.entries(renames)) index = index.split(o).join(n);
write('index.html', index);

const bundle = ls().find((f) => /^main_.*\.js$/.test(f));
const css = ls().find((f) => /^main_.*\.css$/.test(f));
let sw = read('sw.js');
const ver = `${bundle}-${css.match(NAME)[0].split('_').pop().split('.')[0]}`;   // content-derived
if (!/const VERSION = "[^"]*";/.test(sw)) throw new Error('sw.js: VERSION line not found');
sw = sw.replace(/const VERSION = "[^"]*";/, `const VERSION = "${ver}";`);
sw = sw.replace(/'\/' \+ "main_[^"]*\.js"/, `'/' + "${bundle}"`);
write('sw.js', sw);
console.log(`sw.js VERSION = ${ver}`);
